public class MeleeAttackState : SkillState
{
	protected bool skipAttackEvent;

	public GameObject attackPrefab;

	public MeleeAttackObject currentAttackObject;

	protected bool skipAtkObjSpawn;

	public bool setParent;

	public bool destroyAttackObjectOnExit;

	public bool updateSkillLevel;

	public bool attackExecuted;

	public int maxComboCount;

	public int comboCounter = 1;

	public int calcComboCounter;

	public bool repeatFinalHit;

	public float baseCancelThreshold;

	public float finalCancelThreshold;

	public float baseRunThreshold;

	public float finalRunThreshold;

	public float baseExitThreshold;

	public float finalExitThreshold;

	public float finalAttackScale;

	public float penultimateAttackScale;

	public float baseAttackScale;

	public float scaleValue;

	public Vector3 scaleVector;

	public Vector3 calcScaleVector;

	public bool flipObjectForBackhand;

	public bool alwaysStartForehand;

	public bool alwaysStartBackhand;

	public string atkMoveModStr = "MeleeAttackMoveSpeed";

	public NumVarStatMod attackMoveSpeedMod;

	public NumVarStatMod finalAttackMoveSpeedMod;

	public bool allowDirectionChange;

	public bool continueMovement;

	public bool forceMovement;

	public float minDistForMove = 2.25f;

	public Vector2 rotationVector;

	public Vector2 movementVector;

	public bool movementApplied;

	public Vector3 spawnOffset = Vector3.zero;

	public BoolVarStat autoHoldStat = new BoolVarStat(newBaseVal: false);

	public string[] sfxNames;

	public string[] animNames;

	public BoolVarStat fullAutoStat;

	private Vector2 checkAimVec;

	private bool checkAimUpdated;

	public int HitsRemaining => Mathf.Max(0, maxComboCount - comboCounter - (repeatFinalHit ? 1 : 0));

	public MeleeAttackState(string stateName, FSM parentFSM, Player parentEntity)
		: base(stateName, parentFSM, parentEntity)
	{
		allowSelfTransition = true;
		setParent = true;
		destroyAttackObjectOnExit = true;
		updateSkillLevel = true;
		maxComboCount = 3;
		repeatFinalHit = false;
		animStartTime = 0f;
		animExecTime = 0f;
		cancelThreshold = 1f;
		runThreshold = 1f;
		exitThreshold = 1f;
		baseCancelThreshold = cancelThreshold;
		finalCancelThreshold = cancelThreshold;
		baseRunThreshold = runThreshold;
		finalRunThreshold = runThreshold;
		baseExitThreshold = exitThreshold;
		finalExitThreshold = exitThreshold;
		baseAttackScale = 1f;
		penultimateAttackScale = 1f;
		finalAttackScale = 1f;
		scaleValue = 1f;
		scaleVector = Vector3.one;
		calcScaleVector = scaleVector;
		flipObjectForBackhand = true;
		alwaysStartForehand = false;
		alwaysStartBackhand = false;
		attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 4f, 10, VarStatModType.OverrideWithMods);
		finalAttackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 8f, 10, VarStatModType.OverrideWithMods);
		allowDirectionChange = true;
		continueMovement = true;
		forceMovement = false;
		fullAutoStat = new BoolVarStat(newBaseVal: false);
	}

	public virtual void PlayAnimation(int attackCount)
	{
		calcScaleVector = scaleVector;
		ref bool playForehandAnim = ref parent.playForehandAnim;
		bool flag;
		if (alwaysStartForehand)
		{
			flag = attackCount % 2 == 1;
		}
		else
		{
			flag = ((!alwaysStartBackhand) ? parent.playForehandAnim : (attackCount % 2 == 0));
		}
		playForehandAnim = flag;
		parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animStartTime);
		if (!parent.forehandAnimPlayed && flipObjectForBackhand)
		{
			calcScaleVector.x *= -1f;
		}
	}

	public virtual void HandleComboCount(int attackCount)
	{
		allowSelfTransition = true;
		scaleValue = baseAttackScale;
		calcComboCounter = maxComboCount - attackCount;
		if (repeatFinalHit)
		{
			calcComboCounter = Mathf.Max(0, calcComboCounter - 1);
		}
		switch (calcComboCounter)
		{
		case 0:
			scaleValue = finalAttackScale;
			break;
		case 1:
			scaleValue = penultimateAttackScale;

		scaleValue = penultimateAttackScale;
		break;
	}
	if (sfxNames != null && sfxNames.Length > calcComboCounter)
	{
		string audioID = sfxNames[calcComboCounter];
		Vector2? soundOrigin = parent.transform.position;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
	}
	if (animNames != null && animNames.Length > calcComboCounter)
	{
		currentAttackObject.anim.Play(animNames[calcComboCounter], -1, 0f);
	}
}
public virtual void HandleSelfTransition(int attackCount)
{
	if (maxComboCount > attackCount)
	{
		allowSelfTransition = true;
		runThreshold = baseRunThreshold;
		exitThreshold = baseExitThreshold;
	}
	else
	{
		allowSelfTransition = fullAutoStat.CurrentValue;
		runThreshold = finalRunThreshold;
		exitThreshold = finalExitThreshold;
	}
}
public virtual void SetMoveSpeedAndCancelThreshold(int attackCount)
{
	calcComboCounter = maxComboCount - attackCount;
	if (repeatFinalHit)
	{
		calcComboCounter = Mathf.Max(0, calcComboCounter - 1);
	}
	if (calcComboCounter == 0)
	{
		cancelThreshold = finalCancelThreshold;
		parent.movement.moveSpeedStat.AddMod(finalAttackMoveSpeedMod);
	}
	else
	{
		cancelThreshold = baseCancelThreshold;
		parent.movement.moveSpeedStat.AddMod(attackMoveSpeedMod);
	}
}
public virtual bool MovementCheck()
{
	if (ChaosInputDevice.lockControllerAim && !parent.inputDevice.IsMouseAim)
	{
		inputVector = parent.inputDevice.GetAimVector();
		movementVector = parent.inputDevice.GetMoveVector();
		movementApplied = movementVector != Vector2.zero || fsm.previousStateName != name;
	}
	else
	{
		checkAimVec = parent.inputDevice.GetAimVector();
		checkAimUpdated = checkAimVec != Vector2.zero;
		if (checkAimUpdated || fsm.previousStateName != name)
		{
			inputVector = checkAimVec;
		}
		movementVector = checkAimVec;
		movementApplied = checkAimUpdated;
	}
	if (!movementApplied && fsm.previousStateName != name)
	{
		inputVector = Entity.GetFacingDirectionVector(parent.facingDirection);
	}
	if (forceMovement)
	{
		movementApplied = true;
		movementVector = inputVector;
	}
	else if (parent.inputDevice.IsMouseAim && parent.inputDevice.GetMouseDist < minDistForMove)
	{
		return false;
	}
	return movementApplied;
}
public virtual void GetAttackAndMoveVectors(int attackCount)
{
	if (!allowDirectionChange && attackCount > 1)
	{
		if (continueMovement && movementApplied)
		{
			parent.movement.MoveToMoveVector();
		}
	}
	else if (MovementCheck())
	{
		parent.movement.moveVector = movementVector;
		parent.movement.MoveToMoveVector();
	}
}
public virtual void ExecuteAttack()
{
	if (!skipAtkObjSpawn)
	{
		currentAttackObject = Globals.ChaosInst<MeleeAttackObject>(attackPrefab, (!setParent) ? parent.transform.parent : parent.attackOriginTrans, parent.attackOriginTrans.position + spawnOffset);
	}
	HandleComboCount(comboCounter);
	HandleSelfTransition(comboCounter);
	if (!skipAtkObjSpawn)
	{
		currentAttackObject.attack.SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
		currentAttackObject.attack.knockbackOverwriteVector = inputVector;
		currentAttackObject.attackVec = inputVector;
	}
	rotationVector = inputVector;
	if (!parent.isFacingRight && setParent)
	{
		rotationVector.x *= -1f;
	}
	if (!skipAtkObjSpawn)
	{
		currentAttackObject.transform.localEulerAngles = Globals.GetRotationVector(rotationVector);
		currentAttackObject.transform.localScale = calcScaleVector * scaleValue;
	}
	AnnounceSkillExecuteEvent();
}
public override void AnnounceSkillExecuteEvent()
{
	if (!skipAttackEvent)
	{
		base.AnnounceSkillExecuteEvent();
	}
}
public virtual void HandleRepeatLock(bool status, int attackCount)
{
	SetRepeatLock(status);
}
public override void OnEnter()
{
	BaseOnEnter();
	parent.movement.EndMovement();
	if (fsm.previousStateName != fsm.currentStateName)
	{
		comboCounter = 1;
	}
	if (updateSkillLevel)
	{
		SetSkillLevel(comboCounter);
	}
	HandleRepeatLock(!autoHoldStat.CurrentValue, comboCounter);
	SetMoveSpeedAndCancelThreshold(comboCounter);
	GetAttackAndMoveVectors(comboCounter);
	parent.FaceTarget((Vector2)parent.transform.position + inputVector);
	PlayAnimation(comboCounter);
	attackExecuted = false;
	skipAttackEvent = false;
}
public override void Update()
{
	UpdateRepeatLock(string.Empty);
	if (!attackExecuted)
	{
		if (parent.anim.AnimPlayed(animExecTime))
		{
			attackExecuted = true;
			ExecuteAttack();
		}
	}
	else
	{
		ExitToSkillOrRunOrIdle();
	}
}

