			{
				laserFired = true;
				if (currentBeam != null)
				{
					currentBeam.GetComponent<Animator>().Play("Shoot");
				}
			}
		}
		ExitToSkillOrRunOrIdle();
	}
	public override void OnExit()
	{
		base.OnExit();
		if (currentBeam != null)
		{
